INSERT INTO tab_keep_set_hits_src
SELECT number, arrayStringConcat(arrayMap(x -> concat('t', toString(cityHash64(number, x) % 64)), range(30)), ' ')
FROM numbers(1000000);

INSERT INTO tab_keep_set_src
SELECT number, arrayStringConcat(arrayMap(x -> concat('t', toString(toUInt32(pow(100000, cityHash64(number, x) / 18446744073709551616.)) % 100000)), range(30)), ' ')
FROM numbers(1000000);
